    save.onclick=()=>{const value=kind.value==='external'?url.value.trim():target.value;if(!label.value.trim()){error.setText('请填写显示文字');return}if(kind.value==='external'?!owner.validURL(value):!app.vault.getAbstractFileByPath(value)){error.setText(kind.value==='external'?'请填写有效的 http、https 或 mailto 链接':'请选择仍然存在的页面或文档');return}done({kind:kind.value,target:value,text:label.value.trim()});this.close()};
