  function routeSVG(route){const api={esc:s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))};if(!route.length)return '<p class="trip-empty">在表格中添加地点和经纬度；路线会自动更新。</p>';const xs=route.map(x=>Number(x.lng)),ys=route.map(x=>Number(x.lat));if([...xs,...ys].some(x=>!Number.isFinite(x)))return '';const minX=Math.min(...xs),minY=Math.min(...ys),dx=Math.max(...xs)-minX||1,dy=Math.max(...ys)-minY||1;const pts=route.map((r,i)=>({x:55+(xs[i]-minX)/dx*580,y:240-(ys[i]-minY)/dy*190,name:r.name}));return '<svg viewBox="0 0 730 300" role="img" aria-label="按真实经纬度绘制的路线示意"><defs><pattern id="grid" width="35" height="35" patternUnits="userSpaceOnUse"><path d="M 35 0 L 0 0 0 35" fill="none" stroke="#dce4d4" stroke-width=".6"/></pattern></defs><rect width="730" height="300" fill="url(#grid)"/><polyline fill="none" stroke="#7b9364" stroke-width="3" stroke-dasharray="6 6" points="'+pts.map(p=>p.x+','+p.y).join(' ')+'"/>'+pts.map((p,i)=>'<g><circle cx="'+p.x+'" cy="'+p.y+'" r="13" fill="#637b50" stroke="white" stroke-width="3"/><text x="'+p.x+'" y="'+(p.y+4)+'" text-anchor="middle" font-size="11" fill="white">'+(i+1)+'</text><text x="'+Math.min(640,p.x+19)+'" y="'+(p.y+4)+'" font-size="12" fill="#627553">'+api.esc(p.name)+'</text></g>').join('')+'</svg>'}
  function columnIndex(table,key,label,fallback){const headers=[...(table.tHead?.rows[0]?.cells||[])];let found=headers.findIndex(h=>h.dataset.tripColumn===key);if(found>=0)return found;found=headers.findIndex(h=>{const copy=h.cloneNode(true);copy.querySelectorAll('[data-lapian-editor]').forEach(x=>x.remove());return copy.textContent.trim()===label});if(found>=0){headers[found].dataset.tripColumn=key;return found}return fallback}
  let calcTimer;function locationChanged(){clearTimeout(calcTimer);calcTimer=setTimeout(()=>{const routeTable=document.querySelector('[data-trip-route-table]'),routeHost=document.querySelector('[data-trip-route]');if(routeTable&&routeHost){const route=[...(routeTable.tBodies[0]?.rows||[])].map(r=>({name:r.cells[columnIndex(routeTable,'name','地点',0)]?.textContent.replace(/⠿/g,'').trim(),lat:r.cells[columnIndex(routeTable,'lat','纬度',1)]?.textContent.replace(/⠿/g,'').trim(),lng:r.cells[columnIndex(routeTable,'lng','经度',2)]?.textContent.replace(/⠿/g,'').trim()})).filter(r=>r.name&&r.lat&&r.lng&&Number.isFinite(Number(r.lat))&&Number.isFinite(Number(r.lng))&&Math.abs(Number(r.lat))<=90&&Math.abs(Number(r.lng))<=180);routeHost.innerHTML=routeSVG(route);}const table=document.querySelector('[data-trip-budget-table]');if(table){const groups=new Map();let total=0;for(const row of table.tBodies[0]?.rows||[]){const n=Number((row.cells[columnIndex(table,'amount','金额（人民币）',2)]?.textContent||'').replace(/[¥￥,⠿\s]/g,''));if(Number.isFinite(n)&&n>=0){total+=n;const cat=row.cells[columnIndex(table,'category','分类',5)]?.textContent.replace(/⠿/g,'').trim()||'其他';groups.set(cat,(groups.get(cat)||0)+n)}}const label=document.querySelector('[data-trip-total]');if(label)label.innerHTML=total.toLocaleString('zh-CN',{style:'currency',currency:'CNY'})+'<br>总计 · 人民币';const colors=['#637951','#81936d','#9eac8b','#b7c1a7','#ccd3c0','#e0e5d6'];let sum=0;const segments=[...groups].map(([c,n],i)=>{const start=sum;sum+=total?n/total*100:0;return colors[i%colors.length]+' '+start+'% '+sum+'%'});const donut=document.querySelector('.trip-donut');if(donut)donut.style.background=total?'conic-gradient('+segments.join(',')+')':'#e3e8db';const legend=document.querySelector('[data-trip-budget-legend]');if(legend)legend.textContent=[...groups].map(([c,n])=>c+' '+n.toFixed(2)).join(' · ')}},50)}document.addEventListener('input',locationChanged);locationChanged();
