function select(el,label,items,value,fn){const s=el.createEl('select',{attr:{'aria-label':label}});for(const [v,t]of items)s.createEl('option',{value:v,text:t});s.value=value;s.onchange=()=>fn(s.value);return s;}
function metric(row,key){return row.metrics?.[key]?.display??'';}
