function nativeTagBlock(summary){const people=summary.directors||[],grades=[...(summary.grade?['爆款/抖音/'+summary.grade.replace('爆款','')]:[]),...(summary.xhsHit?['爆款/小红书']:[])];if(!people.length&&!grades.length)return '';return '\n<!-- 发布标签（系统） -->\n'+(people.length?'发布内容编导：'+people.map(x=>'#'+directorTag(x)).join(' ')+'\n':'')+(grades.length?'发布内容等级（各平台最高）：'+grades.map(x=>'#'+x).join(' ')+'\n':'')+'<!-- /发布标签（系统） -->\n';}
