 if(f.fm.类型==='视频')button(doc,'尝试识别链接',()=>f.identify(),'pw-text-button');const writing=doc.createDiv({cls:'pw-page-writing'});for(const field of sections){const section=writing.createDiv({cls:'pw-page-section'});f.field(section,field);const input=f.controls[field.name]?.el;if(input){input.rows=1;input.placeholder='写下'+(field.label||field.name)+'…';}}
 const notes=pageBody(f.body||'\n```workspace-record\n```\n\n## 自由笔记\n\n');this.bodyPrefix=notes.prefix;this.notesOriginal=notes.notes;const free=writing.createDiv({cls:'pw-page-section pw-field'});free.createEl('label',{text:'自由笔记'});this.notesInput=free.createEl('textarea',{attr:{rows:'2','aria-label':'自由笔记',placeholder:'在这里继续写作…'}});this.notesInput.value=notes.notes;UnifiedLinks.bind(f,this.notesInput,'自由笔记',free);this.store.plugin.ai?.bindField(this.notesInput,'自由笔记');
