 async saved(record,options={}){if(options.autosave){await this.writeQueue;this.form.old=record;this.form.fm=clone(record.fm);this.form.body=record.body;const newer=(this.editVersion||0)>(options.revision||0);this.dirty=newer;if(newer){this.capture();clearTimeout(this.draftTimer);this.draftTimer=setTimeout(async()=>{await this.persistDraft();await this.tryAutosave()},800)}else{this.stateEl?.setText('已自动保存 · 可直接编辑');this.form.error?.setText('');const path=this.draftPath();if(await this.app.vault.adapter.exists(path))await this.app.vault.adapter.remove(path)}this.app.workspace.requestSaveLayout();return}clearTimeout(this.draftTimer);await this.writeQueue;const path=this.draftPath();if(await this.app.vault.adapter.exists(path))await this.app.vault.adapter.remove(path);this.dirty=false;this.form.old=record;this.form.fm=clone(record.fm);this.form.body=record.body;this.form.pendingFiles=[];this.form.controls={};this.notesInput=null;this.renderForm();this.app.workspace.requestSaveLayout();}
