  const actions=e.createDiv({cls:'pw-inline'});if(fm.已删除)button(actions,'恢复本地记录',async()=>{if(fm.系统日历?.remoteDeleted){new Notice('恢复本地副本，不自动重建已删除的系统日程。需要重新同步时请新建日程。',9000);await this.store.save({...fm,已删除:null,确认同步删除:false,同步状态:'本地恢复副本',系统日历:{...fm.系统日历,writable:false,readOnlyReason:'本地恢复副本，不自动重建来源'}},r);}else await this.store.restore(r);this.draw()});else button(actions,'编辑',()=>{this.close();new RecordForm(this.store,fm.类型,r,{},saved=>new DetailModal(this.store,saved).open()).open()},'mod-cta');button(actions,'打开原始笔记',async()=>{this.close();await this.app.workspace.getLeaf(false).openFile(r.file)});
  if(!fm.已删除)button(actions,'移入回收站',async()=>{if(!fm.系统日历){await this.store.deleteWithUndo(r);this.close();return}const answer=await new Choice(this.app,'移入回收站？',false?'此操作将在下次同步时删除系统日历中的这一条日程；重复日程只删除本次。工作台保留本地副本。':fm.系统日历?'只从工作台隐藏此只读日程，不修改系统来源。':'资料保留在工作台中，可随时恢复；关联资料不会被级联删除。',[{label:'移入回收站',value:true},{label:'取消',value:false}]).ask();if(answer){if(false)await this.store.save({...fm,已删除:now(),确认同步删除:true},r);else await this.store.remove(r);this.close()}});
