function navPartition(id){return id==='home'||(String(id).startsWith('module:')||String(id).startsWith('book:'))?'notes':'system';}
function orderSidebarItems(items,order=[]){return [...items].sort((a,b)=>{const group=(navPartition(a.id)==='notes'?0:1)-(navPartition(b.id)==='notes'?0:1);if(group)return group;const x=order.indexOf(a.id),y=order.indexOf(b.id);return (x<0?order.length:x)-(y<0?order.length:y)})}
function canMoveSidebarItems(id,target){return id!==target&&navPartition(id)===navPartition(target);}
function scriptTitleInfo(record){const title=String(record.fm?.名称||record.file?.basename||'').trim(),match=title.match(/^(\d{4})(\d{2})(\d{2})(?!\d)/);let date='';if(match){const year=+match[1],month=+match[2],day=+match[3],d=new Date(Date.UTC(year,month-1,day));if(year>=1900&&year<=2199&&d.getUTCFullYear()===year&&d.getUTCMonth()===month-1&&d.getUTCDate()===day)date=match[1]+match[2]+match[3];}const director=title.match(/【([^】]+)】/)?.[1]?.trim()||'未标注编导';return {date,director};}
function compareScriptTime(a,b,ascending=false){const x=scriptTitleInfo(a).date,y=scriptTitleInfo(b).date;if(!x||!y)return x?-1:y?1:String(a.fm.名称).localeCompare(String(b.fm.名称),'zh-CN');return (ascending?x.localeCompare(y):y.localeCompare(x))||String(a.fm.名称).localeCompare(String(b.fm.名称),'zh-CN');}
