  const lead=intro.createDiv();
  lead.createEl('small',{cls:'pw-eyebrow',text:this.store.config.modeNames[this.mode]+' / 我的资料'});
  lead.createEl('h1',{text:this.store.config.title||'个人工作台'});
  lead.createEl('p',{cls:'pw-muted',text:this.mode==='工作'?'收藏灵感，整理调研，接着写上次的脚本。':'记录学习、兴趣与旅行安排。'});
