 calendar(el){this.heading(el,this.currentModule().name,this.currentModule().description||'点击日期新增安排；状态和详情可随时编辑。','日程');const toolbar=el.createDiv({cls:'pw-toolbar'});button(toolbar,'← 上月',()=>{this.month.setMonth(this.month.getMonth()-1);this.draw()});toolbar.createEl('strong',{text:this.month.getFullYear()+' 年 '+(this.month.getMonth()+1)+' 月'});button(toolbar,'下月 →',()=>{this.month.setMonth(this.month.getMonth()+1);this.draw()});button(toolbar,'本月',()=>{this.month=new Date();this.month.setDate(1);this.draw()});toolbar.createEl('small',{text:'今天：'+dated(today()),cls:'pw-today-label'});el.createEl('small',{text:'日程仅保存在当前笔记库，不连接系统日历。'});const grid=el.createDiv({cls:'pw-calendar'});for(const day of ['星期一','星期二','星期三','星期四','星期五','星期六','星期日'])grid.createEl('small',{text:day,cls:'pw-weekday'});const start=(this.month.getDay()+6)%7;for(let i=0;i<start;i++)grid.createDiv({cls:'pw-calendar-pad'});for(let day=1;day<=new Date(this.month.getFullYear(),this.month.getMonth()+1,0).getDate();day++){const date=[this.month.getFullYear(),String(this.month.getMonth()+1).padStart(2,'0'),String(day).padStart(2,'0')].join('-');const cell=grid.createDiv({cls:'pw-calendar-day'+(date===today()?' is-today':'')});const dayButton=button(cell,String(day),()=>new RecordForm(this.store,'日程',null,this.preset('日程',{日期:date})).open(),'pw-day-number');dayButton.setAttribute('aria-label',dated(date)+'，新增日程');dayButton.setAttribute('title',dated(date));for(const r of this.store.moduleRecords(this.section).filter(r=>dateText(r.fm.日期)===date).sort((a,b)=>String(a.fm.开始时间).localeCompare(String(b.fm.开始时间))))button(cell,(r.fm.开始时间||'')+' '+r.fm.名称,()=>new DetailModal(this.store,r).open(),'pw-event');}el.createEl('h2',{text:'接下来的安排'});this.renderRows(el,this.store.moduleRecords(this.section).filter(r=>dateText(r.fm.日期)>=today()).sort((a,b)=>dateText(a.fm.日期).localeCompare(dateText(b.fm.日期))).slice(0,10),'列表');}
 interests(el){if(this.activeInterest){const space=this.store.get(this.activeInterest);if(!space||!active(space)){this.activeInterest='';this.draw();return}button(el,'← 所有兴趣',()=>{this.activeInterest='';this.filters={};this.draw()});button(el,'板块设置与自定义字段',()=>new RecordForm(this.store,'兴趣板块',space).open());this.library(el,'兴趣记录',{所属兴趣:wikilink(space.file.path)});return;}this.heading(el,this.currentModule().name,this.currentModule().description||'每个板块可以命名、排序，并拥有自己的字段。','兴趣板块');const rows=this.store.moduleRecords(this.section).sort((a,b)=>(a.fm.排序||0)-(b.fm.排序||0)||String(a.fm.名称).localeCompare(String(b.fm.名称),'zh-CN'));if(!rows.length){if(this.mode!=='私人')this.renderRows(el,[]);return}const grid=el.createDiv({cls:'pw-grid'});for(let i=0;i<rows.length;i++){const r=rows[i],card=grid.createDiv({cls:'pw-home-card'});button(card,r.fm.名称,()=>{this.activeInterest=r.file.path;this.filters={};this.draw()},'pw-card-title');card.createEl('p',{text:r.fm.板块说明||'收集链接、照片与自己的记录'});card.createEl('small',{text:this.store.records('兴趣记录').filter(x=>sameRef(x.fm.所属兴趣,r.file.path)).length+' 条记录 · '+list(r.fm.字段定义).length+' 个自定义字段'});const controls=card.createDiv({cls:'pw-inline'});button(controls,'设置',()=>new RecordForm(this.store,'兴趣板块',r).open());if(i>0)button(controls,'上移',async()=>{const ordered=[...rows];[ordered[i],ordered[i-1]]=[ordered[i-1],ordered[i]];for(let j=0;j<ordered.length;j++)await this.store.save({...ordered[j].fm,排序:j},this.store.get(ordered[j].file.path));});button(controls,'删除板块',async()=>{const choice=await new Choice(this.app,'删除兴趣板块？','关联记录将一起进入回收站，照片和原文保留，可分别恢复。',[{label:'移入回收站',value:true},{label:'取消',value:false}]).ask();if(!choice)return;for(const child of this.store.records('兴趣记录').filter(x=>sameRef(x.fm.所属兴趣,r.file.path)))await this.store.remove(child);await this.store.remove(this.store.get(r.file.path));});}}
