const {PluginSettingTab:ProfileTab,Setting:ProfileSetting}=require('obsidian');
const OriginalWorkspaceSpace=module.exports;
module.exports=class WorkspaceSpacePortable extends OriginalWorkspaceSpace {
 async onload(){
  this.profileBusy=false;
  this.addSettingTab(new WorkspaceProfileSettings(this.app,this));
  this.addCommand({id:'install-profile',name:'安装模板与设置',callback:()=>this.openProfile()});
  this.addCommand({id:'restore-profile',name:'恢复最近一次配置导入',callback:()=>this.restoreProfile().catch(e=>new Notice(e.message))});
  if(await this.app.vault.adapter.exists('Workspace/系统（系统）/模块配置（系统）.json'))await super.onload();
  else new Notice('请在 Workspace 设置中安装模板与配置，然后重新加载插件。',10000);
 }
 openProfile(){this.app.setting.open();this.app.setting.openTabById(this.manifest.id);}
 profilePath(p){return p.startsWith('.CONFIG_SNIPPET/')?this.app.vault.configDir+'/snippets/'+p.split('/').pop():p;}
 async mkdirProfile(p){const a=this.app.vault.adapter;let cur='';for(const bit of p.split('/').slice(0,-1)){cur=cur?cur+'/'+bit:bit;if(!await a.exists(cur))await a.mkdir(cur);}}
 async applyProfile(settings=false,overwrite=false){
  if(this.profileBusy)throw Error('配置任务正在运行');this.profileBusy=true;
  const a=this.app.vault.adapter,base=this.app.vault.configDir+'/plugins/'+this.manifest.id;
  const backup=base+'/profile-backups/'+Date.now()+'.json',journal={version:1,entries:[]};
  try{
   const writes=Object.entries(WORKSPACE_PROFILE.assets).map(([p,text])=>[this.profilePath(p),text]);
   if(settings)for(const [name,value]of Object.entries(WORKSPACE_PROFILE.configs)){
    const p=this.app.vault.configDir+'/'+name;let old={};
    if(await a.exists(p)){old=JSON.parse(await a.read(p));if(!old||Array.isArray(old)||typeof old!=='object')throw Error('配置格式异常：'+name);}
    const merged={...old,...value};if(name==='appearance.json')merged.enabledCssSnippets=[...new Set([...(old.enabledCssSnippets||[]),...(value.enabledCssSnippets||[])])];
    writes.push([p,JSON.stringify(merged,null,2)]);
   }
   // Resolve all conflicts before mutation, then persist a complete recovery journal.
   const plan=[];
   for(const [path,text]of writes){const exists=await a.exists(path);if(exists&&!overwrite&&!Object.keys(WORKSPACE_PROFILE.configs).some(n=>settings&&path===this.app.vault.configDir+'/'+n))continue;const before=exists?await a.read(path):null;if(before===text)continue;plan.push({path,before,after:text});}
   if(!plan.length){new Notice('所有资源已存在，没有修改文件');return;}
   journal.entries=plan;await this.mkdirProfile(backup);await a.write(backup,JSON.stringify(journal));
   await a.write(base+'/profile-last-backup.json',JSON.stringify({path:backup}));
   for(const item of plan){await this.mkdirProfile(item.path);await a.write(item.path,item.after);}
   // Create empty folders required by the bundled vault settings.
   for(const dir of ['00 收件箱','90 附件','40 日记'])await this.mkdirProfile(dir+'/placeholder');
   new Notice('已安装 '+plan.length+' 个文件。请重启 Obsidian 使设置生效。备份：'+backup,12000);
  }catch(e){
   if(journal.entries.length)for(const item of [...journal.entries].reverse())try{if(item.before===null){if(await a.exists(item.path)&&await a.read(item.path)===item.after)await a.remove(item.path);}else if(await a.exists(item.path)&&await a.read(item.path)===item.after)await a.write(item.path,item.before);}catch{}
   throw e;
  }finally{this.profileBusy=false;}
 }
 async restoreProfile(){
  if(this.profileBusy)throw Error('配置任务正在运行');this.profileBusy=true;
  try{
   const a=this.app.vault.adapter,base=this.app.vault.configDir+'/plugins/'+this.manifest.id;
   const pointer=JSON.parse(await a.read(base+'/profile-last-backup.json'));
   const journal=JSON.parse(await a.read(pointer.path));let restored=0,skipped=0;
   const allowed=new Set([...Object.keys(WORKSPACE_PROFILE.assets).map(p=>this.profilePath(p)),...Object.keys(WORKSPACE_PROFILE.configs).map(n=>this.app.vault.configDir+'/'+n)]);
   for(const item of journal.entries){if(!allowed.has(item.path))throw Error('备份包含不受支持的路径');}
   for(const item of [...journal.entries].reverse()){
    if(!await a.exists(item.path)||await a.read(item.path)!==item.after){skipped++;continue;}
    if(item.before===null)await a.remove(item.path);else await a.write(item.path,item.before);restored++;
   }
   new Notice('已恢复 '+restored+' 个文件；跳过 '+skipped+' 个已修改文件。请重启 Obsidian。',10000);
  }finally{this.profileBusy=false;}
 }
};
class WorkspaceProfileSettings extends ProfileTab{
 display(){const el=this.containerEl;el.empty();el.createEl('h2',{text:'Workspace 配置包'});
 el.createEl('p',{text:'包含当前工作台、报告模板、数据库视图、样式和可迁移设置。不会自动覆盖已有模板；导入全局设置需单独操作。支持电脑、iPhone 和 iPad；iPad 横屏保留接近电脑端的侧栏布局。'});
 const run=fn=>{if(this.plugin.profileBusy)return;Promise.resolve().then(fn).catch(e=>new Notice('操作失败：'+e.message,10000));};
 new ProfileSetting(el).setName('安装缺失模板与视图').setDesc('推荐先在空白库使用。保留已有文件，备份后补齐缺少的资源。').addButton(b=>b.setButtonText('安装资源').setCta().onClick(()=>run(()=>this.plugin.applyProfile())));
 new ProfileSetting(el).setName('应用设置与外观').setDesc('合并导入编辑器、核心插件开关、快捷键、日记和模板目录；同名设置将被替换。先备份，应用后重启。').addButton(b=>b.setButtonText('应用配置').onClick(()=>run(()=>this.plugin.applyProfile(true))));
 new ProfileSetting(el).setName('覆盖已有模板').setDesc('明确勾选后可将当前模板替换为包内版本；操作前保存恢复备份。').addToggle(t=>t.onChange(v=>{this.overwrite=v;})).addButton(b=>b.setButtonText('重新安装模板').onClick(()=>{if(!this.overwrite){new Notice('请先勾选允许覆盖');return;}run(()=>this.plugin.applyProfile(false,true));}));
 new ProfileSetting(el).setName('恢复上次导入').setDesc('恢复到导入前状态；导入后又手动修改过的文件会保留。').addButton(b=>b.setButtonText('恢复').onClick(()=>run(()=>this.plugin.restoreProfile())));
 }
}
